<script setup lang="ts">
import { onMounted,ref,reactive } from 'vue';
import { ElMessage } from 'element-plus';
import { api,errorText } from '../../api/zenflow/client';
import EmbeddingModels from './EmbeddingModels.vue';
interface Model{id:string;name:string;modelName:string;provider:string;baseUrl:string;temperature:number;maxOutputTokens:number;contextWindow:number;apiProtocol:string;version:number;active:boolean;published:boolean;tested:boolean;hasApiKey:boolean;allowPrivateContext:boolean}
const rows=ref<Model[]>([]),loading=ref(false),busy=ref(''),open=ref(false),editing=ref('');
const form=reactive({name:'',modelName:'',provider:'OpenAI-compatible',baseUrl:'',apiKey:'',temperature:0.6,maxOutputTokens:2048,contextWindow:32768,apiProtocol:'OPENAI_CHAT_COMPLETIONS',allowPrivateContext:false,expectedVersion:0});
async function load(){loading.value=true;try{rows.value=(await api.get('/models')).data;}catch(e){ElMessage.error(errorText(e));}finally{loading.value=false;}}
function edit(row?:Model){editing.value=row?.id||'';Object.assign(form,{name:row?.name||'',modelName:row?.modelName||'',provider:row?.provider||'OpenAI-compatible',baseUrl:row?.baseUrl||'',apiKey:'',temperature:row?.temperature??0.6,maxOutputTokens:row?.maxOutputTokens||2048,contextWindow:row?.contextWindow||32768,apiProtocol:row?.apiProtocol||'OPENAI_CHAT_COMPLETIONS',allowPrivateContext:row?.allowPrivateContext||false,expectedVersion:row?.version||0});open.value=true;}
async function save(){busy.value='save';try{if(editing.value)await api.put('/models/'+editing.value,form);else await api.post('/models',form);form.apiKey='';open.value=false;ElMessage.success('配置已保存，请先测试再激活');await load();}catch(e){ElMessage.error(errorText(e));}finally{busy.value='';}}
async function test(row:Model){busy.value=row.id;try{await api.post('/models/'+row.id+'/test',{expectedVersion:row.version});ElMessage.success('流式连通测试通过');await load();}catch(e){ElMessage.error(errorText(e));}finally{busy.value='';}}
async function activate(row:Model){busy.value=row.id;try{await api.post('/models/'+row.id+'/activate',{expectedVersion:row.version});ElMessage.success('模型已激活，请在陪伴配置中准备并发布对应版本');await load();}catch(e){ElMessage.error(errorText(e));}finally{busy.value='';}}
onMounted(load);
</script>
<template><div><el-tabs><el-tab-pane label="聊天模型"><div class="page-heading"><div><div class="eyebrow">MODEL CONNECTION</div><h1>模型配置</h1><p class="muted">先保存并测试连接，再激活。App 根据服务状态开放对话。</p></div><el-button type="primary" @click="edit()">添加模型</el-button></div>
 <el-alert title="密钥只用于服务端调用，不会返回浏览器或 App。请使用此产品专用凭据。" type="info" :closable="false"/>
 <div v-loading="loading" class="models"><el-empty v-if="!rows.length" description="尚未配置模型，添加后即可进行连通测试。"/><article v-for="row in rows" :key="row.id" class="model-card"><div class="card-heading"><h2>{{row.name}}</h2><el-tag :type="row.active?'success':'info'">{{row.active?'正在使用':row.tested?'已测试':'待测试'}}</el-tag></div><p>{{row.modelName}} · {{row.provider}}</p><p class="endpoint">{{row.baseUrl}}</p><p class="muted">密钥{{row.hasApiKey?'已设置':'未设置'}} · 私人上下文{{row.allowPrivateContext?'已允许':'未允许'}} · 版本 {{row.version}}</p><div class="actions"><el-button :disabled="row.active||row.published||!!busy" @click="edit(row)">编辑</el-button><el-button :loading="busy===row.id" :disabled="!!busy" @click="test(row)">测试连接</el-button><el-button type="primary" :disabled="row.active||!row.tested||!!busy" @click="activate(row)">激活</el-button></div></article></div>
 <el-dialog v-model="open" :title="editing?'编辑模型':'添加模型'" width="min(580px,94vw)" :close-on-click-modal="false" @closed="form.apiKey=''">
 <el-form label-position="top"><el-form-item label="显示名称"><el-input v-model="form.name" maxlength="64" placeholder="例如：此间陪伴模型"/></el-form-item><el-form-item label="模型标识"><el-input v-model="form.modelName" maxlength="100" placeholder="供应商提供的模型名称"/></el-form-item><el-form-item label="供应商标签"><el-input v-model="form.provider" maxlength="100"/></el-form-item><el-form-item label="接口协议"><el-select v-model="form.apiProtocol"><el-option label="OpenAI · Chat Completions" value="OPENAI_CHAT_COMPLETIONS"/><el-option label="Anthropic · Messages（含 MiniMax 兼容接口）" value="ANTHROPIC_MESSAGES"/></el-select></el-form-item><el-form-item label="API 基础地址"><el-input v-model="form.baseUrl" maxlength="100" placeholder="https://供应商地址/v1"/><span class="muted">{{form.apiProtocol==='ANTHROPIC_MESSAGES'?'Anthropic 或 MiniMax 兼容基础地址，如 https://api.minimax.io/anthropic。':'OpenAI 兼容基础地址，如 https://供应商地址/v1。'}}</span></el-form-item><el-form-item label="API 密钥"><el-input v-model="form.apiKey" type="password" autocomplete="new-password" show-password :placeholder="editing?'留空保留已有密钥':'仅保存在服务端'"/></el-form-item><div class="form-row"><el-form-item label="温度"><el-input-number v-model="form.temperature" :min="0" :max="2" :step="0.1"/></el-form-item><el-form-item label="上下文容量 token"><el-input-number v-model="form.contextWindow" :min="2048" :max="2000000" :step="1024"/><span class="muted">填写供应商公布的模型容量，包含输入与输出。</span></el-form-item><el-form-item label="最大输出 token"><el-input-number v-model="form.maxOutputTokens" :min="64" :max="16384" :step="256"/></el-form-item></div><el-form-item><el-checkbox v-model="form.allowPrivateContext">允许此模型接收用户明确选入的私人记录</el-checkbox><span class="muted">仅作用于已授权片段；管理员无法查看个人正文。</span></el-form-item></el-form><template #footer><el-button :disabled="!!busy" @click="open=false">取消</el-button><el-button type="primary" :loading="busy==='save'" @click="save">保存配置</el-button></template></el-dialog>
</el-tab-pane><el-tab-pane label="嵌入模型"><EmbeddingModels/></el-tab-pane></el-tabs></div></template>
